    ["If some live module keeps the previous palette, use Reload UI after saving the style."] = { "Si algún módulo activo conserva la paleta anterior, recarga la interfaz tras guardar el estilo.", "Falls ein aktives Modul die vorherige Palette behält, lade die Oberfläche nach dem Speichern des Stils neu.", "Si un module actif conserve l'ancienne palette, rechargez l'interface après avoir enregistré le style.", "Se un modulo attivo mantiene la palette precedente, ricarica l'interfaccia dopo aver salvato lo stile.", "Se algum módulo ativo mantiver a paleta anterior, recarregue a interface após salvar o estilo.", "Если какой-то активный модуль сохранил прежнюю палитру, перезагрузите интерфейс после сохранения стиля.", "일부 활성 모듈이 이전 팔레트를 유지하면 스타일을 저장한 뒤 UI를 다시 불러오세요.", "如果某个已启用的模块仍保留之前的配色，请在保存样式后重新加载界面。", "如果某個已啟用的模組仍保留先前的配色，請在儲存樣式後重新載入介面。" },
    ["Action Bar Art"] = { "Arte de la barra de acción", "Aktionsleisten-Grafik", "Décor de la barre d'action", "Grafica della barra azioni", "Arte da barra de ação", "Оформление панели действий", "행동 단축바 장식", "动作条装饰", "快捷列裝飾" },
    ["End-cap artwork around the main bar. Respects Edit Mode's Hide Bar Art."] = { "Adornos laterales alrededor de la barra principal. Respeta la opción Ocultar arte de la barra del Modo de edición.", "Endkappen-Grafik um die Hauptleiste. Beachtet „Leistengrafik ausblenden“ des Bearbeitungsmodus.", "Ornements latéraux autour de la barre principale. Respecte l'option « Masquer le décor de la barre » du mode Édition.", "Decorazioni laterali attorno alla barra principale. Rispetta l'opzione Nascondi grafica barra della modalità Modifica.", "Ornamentos laterais ao redor da barra principal. Respeita a opção Ocultar arte da barra do Modo de Edição.", "Боковые украшения вокруг основной панели. Учитывает параметр «Скрыть оформление панели» режима правки.", "주 단축바 양옆의 장식입니다. 편집 모드의 '단축바 장식 숨기기'를 따릅니다.", "主动作条两侧的装饰。遵循编辑模式中的“隐藏动作条装饰”设置。", "主快捷列兩側的裝飾。遵循編輯模式中的「隱藏快捷列裝飾」設定。" },
    ["Forever client art"] = { "Arte del cliente Forever", "Grafik des Forever-Clients", "Décor du client Forever", "Grafica del client Forever", "Arte do cliente Forever", "Оформление клиента Forever", "Forever 클라이언트 아트", "Forever 客户端美术", "Forever 用戶端美術" },
    ["Dwarf end caps"] = { "Remates de enano", "Zwergen-Endkappen", "Ornements nains", "Decorazioni nanesche", "Ornamentos de anão", "Дворфийские украшения", "드워프 장식", "矮人风格装饰", "矮人風格裝飾" },
    ["Click Channel to Chat"] = { "Clic en canal para chatear", "Kanal anklicken, um zu schreiben", "Cliquer sur le canal pour écrire", "Clic sul canale per scrivere", "Clicar no canal para conversar", "Клик по каналу для ввода", "채널 클릭으로 채팅 입력", "点击频道开始输入", "點擊頻道開始輸入" },
    ["+ Suppress GCD"] = { "+ Suprimir GCD", "+ GCD unterdrücken", "+ Masquer le GCD", "+ Sopprimi GCD", "+ Suprimir GCD", "+ Скрыть GCD", "+ 공용 대기시간 숨김", "+ 隐藏公共冷却", "+ 隱藏公共冷卻" },
    ["Suppresses the global-cooldown swipe for this rule."] = { "Suprime la animación del enfriamiento global para esta regla.", "Unterdrückt die Animation der globalen Abklingzeit für diese Regel.", "Masque l'animation du temps de recharge global pour cette règle.", "Sopprime l'animazione del tempo di recupero globale per questa regola.", "Suprime a animação do tempo de recarga global para esta regra.", "Скрывает анимацию общего восстановления для этого правила.", "이 규칙에서 공용 대기시간 애니메이션을 숨깁니다.", "为此规则隐藏公共冷却的扫描动画。", "為此規則隱藏公共冷卻的掃描動畫。" },
    ["+ Hide Charge Text"] = { "+ Ocultar texto de cargas", "+ Aufladungstext ausblenden", "+ Masquer le texte des charges", "+ Nascondi testo delle cariche", "+ Ocultar texto de cargas", "+ Скрыть текст зарядов", "+ 충전 횟수 텍스트 숨김", "+ 隐藏充能文字", "+ 隱藏充能文字" },
    ["Hides the spell charge counter."] = { "Oculta el contador de cargas del hechizo.", "Blendet den Aufladungszähler des Zaubers aus.", "Masque le compteur de charges du sort.", "Nasconde il contatore delle cariche dell'incantesimo.", "Oculta o contador de cargas da magia.", "Скрывает счётчик зарядов заклинания.", "주문의 충전 횟수 표시를 숨깁니다.", "隐藏法术的充能计数。", "隱藏法術的充能計數。" },
    ["+ Hide Swipe (Charges)"] = { "+ Ocultar animación (cargas)", "+ Animation ausblenden (Aufladungen)", "+ Masquer l'animation (charges)", "+ Nascondi animazione (cariche)", "+ Ocultar animação (cargas)", "+ Скрыть анимацию (заряды)", "+ 애니메이션 숨김 (충전)", "+ 隐藏扫描动画（充能）", "+ 隱藏掃描動畫（充能）" },
    ["Hides the recharge swipe while at least one charge remains."] = { "Oculta la animación de recarga mientras quede al menos una carga.", "Blendet die Aufladeanimation aus, solange mindestens eine Aufladung übrig ist.", "Masque l'animation de recharge tant qu'il reste au moins une charge.", "Nasconde l'animazione di ricarica finché resta almeno una carica.", "Oculta a animação de recarga enquanto restar pelo menos uma carga.", "Скрывает анимацию перезарядки, пока остаётся хотя бы один заряд.", "충전이 하나 이상 남아 있는 동안 재충전 애니메이션을 숨깁니다.", "只要还剩至少一层充能，就隐藏充能扫描动画。", "只要還剩至少一層充能，就隱藏充能掃描動畫。" },
    ["+ Hide Recharge Edge"] = { "+ Ocultar borde de recarga", "+ Aufladekante ausblenden", "+ Masquer le bord de recharge", "+ Nascondi bordo di ricarica", "+ Ocultar borda de recarga", "+ Скрыть кромку перезарядки", "+ 재충전 테두리 숨김", "+ 隐藏充能边缘", "+ 隱藏充能邊緣" },
    ["Hides the bright recharge edge."] = { "Oculta el borde brillante de recarga.", "Blendet die helle Aufladekante aus.", "Masque le bord lumineux de recharge.", "Nasconde il bordo luminoso di ricarica.", "Oculta a borda brilhante de recarga.", "Скрывает яркую кромку перезарядки.", "밝은 재충전 테두리를 숨깁니다.", "隐藏明亮的充能边缘。", "隱藏明亮的充能邊緣。" },
    ["Hides recharge duration text while a charge remains."] = { "Oculta el texto de duración de recarga mientras quede una carga.", "Blendet den Text der Aufladedauer aus, solange eine Aufladung übrig ist.", "Masque le texte de durée de recharge tant qu'il reste une charge.", "Nasconde il testo della durata di ricarica finché resta una carica.", "Oculta o texto de duração da recarga enquanto restar uma carga.", "Скрывает текст времени перезарядки, пока остаётся заряд.", "충전이 남아 있는 동안 재충전 시간 텍스트를 숨깁니다.", "还有充能时，隐藏充能时长文字。", "還有充能時，隱藏充能時長文字。" },
    ["+ Stay Hidden While Charges Remain"] = { "+ Mantener oculto mientras queden cargas", "+ Verborgen bleiben, solange Aufladungen übrig sind", "+ Rester masqué tant qu'il reste des charges", "+ Resta nascosto finché restano cariche", "+ Permanecer oculto enquanto restarem cargas", "+ Оставаться скрытым, пока есть заряды", "+ 충전이 남아 있는 동안 숨김 유지", "+ 有剩余充能时保持隐藏", "+ 有剩餘充能時保持隱藏" },
    ["For CD-ready hiding, keeps the icon hidden until all available charges are spent."] = { "Para el ocultado con CD listo, mantiene el icono oculto hasta gastar todas las cargas disponibles.", "Beim Ausblenden bei bereiter Abklingzeit bleibt das Symbol verborgen, bis alle verfügbaren Aufladungen verbraucht sind.", "Pour le masquage « recharge prête », garde l'icône masquée jusqu'à épuisement de toutes les charges disponibles.", "Per il nascondimento a recupero pronto, mantiene l'icona nascosta finché tutte le cariche disponibili non sono esaurite.", "Para o ocultamento com recarga pronta, mantém o ícone oculto até que todas as cargas disponíveis sejam gastas.", "При скрытии «КД готов» значок остаётся скрытым, пока не потрачены все доступные заряды.", "재사용 대기 완료 시 숨김에서, 사용 가능한 충전을 모두 소모할 때까지 아이콘을 숨긴 채로 유지합니다.", "用于“冷却就绪时隐藏”：在所有可用充能用完之前，图标保持隐藏。", "用於「冷卻就緒時隱藏」：在所有可用充能用完之前，圖示保持隱藏。" },
    ["Lower Alpha (On CD)"] = { "Menor opacidad (en CD)", "Geringere Deckkraft (bei Abklingzeit)", "Opacité réduite (en recharge)", "Opacità ridotta (in recupero)", "Opacidade reduzida (em recarga)", "Меньшая непрозрачность (на КД)", "투명도 낮춤 (재사용 대기 중)", "降低透明度（冷却中）", "降低透明度（冷卻中）" },
    ["Reduces icon opacity while the spell is on cooldown."] = { "Reduce la opacidad del icono mientras el hechizo está en enfriamiento.", "Verringert die Deckkraft des Symbols, solange der Zauber in der Abklingzeit ist.", "Réduit l'opacité de l'icône tant que le sort est en recharge.", "Riduce l'opacità dell'icona mentre l'incantesimo è in recupero.", "Reduz a opacidade do ícone enquanto a magia está em recarga.", "Уменьшает непрозрачность значка, пока заклинание на перезарядке.", "주문이 재사용 대기 중일 때 아이콘 투명도를 낮춥니다.", "法术冷却期间降低图标不透明度。", "法術冷卻期間降低圖示不透明度。" },
    ["Hidden on CD (Shift Icons)"] = { "Oculto en CD (desplazar iconos)", "Bei Abklingzeit verborgen (Symbole rücken nach)", "Masqué en recharge (décaler les icônes)", "Nascosto in recupero (sposta icone)", "Oculto em recarga (deslocar ícones)", "Скрыт на КД (сдвигать значки)", "재사용 대기 중 숨김 (아이콘 이동)", "冷却中隐藏（图标补位）", "冷卻中隱藏（圖示補位）" },
    ["Hidden while on cooldown. Remaining icons close the gap."] = { "Oculto mientras está en enfriamiento. Los demás iconos cierran el hueco.", "Verborgen, solange die Abklingzeit läuft. Die übrigen Symbole schließen die Lücke.", "Masqué pendant la recharge. Les autres icônes comblent l'espace.", "Nascosto durante il recupero. Le altre icone chiudono lo spazio.", "Oculto durante a recarga. Os demais ícones preenchem o espaço.", "Скрыт, пока заклинание на перезарядке. Остальные значки смыкаются.", "재사용 대기 중에는 숨겨집니다. 나머지 아이콘이 빈자리를 채웁니다.", "冷却期间隐藏，其余图标会补上空位。", "冷卻期間隱藏，其餘圖示會補上空位。" },
    ["Hidden CD Ready (Shift Icons)"] = { "Oculto con CD listo (desplazar iconos)", "Bei bereiter Abklingzeit verborgen (Symbole rücken nach)", "Masqué si prêt (décaler les icônes)", "Nascosto se pronto (sposta icone)", "Oculto com recarga pronta (deslocar ícones)", "Скрыт при готовности (сдвигать значки)", "사용 가능 시 숨김 (아이콘 이동)", "就绪时隐藏（图标补位）", "就緒時隱藏（圖示補位）" },
    ["Hidden while off cooldown. Remaining icons close the gap."] = { "Oculto mientras no está en enfriamiento. Los demás iconos cierran el hueco.", "Verborgen, solange keine Abklingzeit läuft. Die übrigen Symbole schließen die Lücke.", "Masqué hors recharge. Les autres icônes comblent l'espace.", "Nascosto quando non è in recupero. Le altre icone chiudono lo spazio.", "Oculto quando fora de recarga. Os demais ícones preenchem o espaço.", "Скрыт, когда заклинание не на перезарядке. Остальные значки смыкаются.", "재사용 대기 중이 아닐 때 숨겨집니다. 나머지 아이콘이 빈자리를 채웁니다.", "不在冷却时隐藏，其余图标会补上空位。", "不在冷卻時隱藏，其餘圖示會補上空位。" },
    ["Hidden Until Usable (Shift Icons)"] = { "Oculto hasta que sea usable (desplazar iconos)", "Verborgen bis nutzbar (Symbole rücken nach)", "Masqué jusqu'à utilisable (décaler les icônes)", "Nascosto finché utilizzabile (sposta icone)", "Oculto até ser utilizável (deslocar ícones)", "Скрыт, пока недоступно (сдвигать значки)", "사용 가능해질 때까지 숨김 (아이콘 이동)", "可用前隐藏（图标补位）", "可用前隱藏（圖示補位）" },
    ["Only shown while usable and off cooldown. Low resources do not hide it."] = { "Solo se muestra mientras es usable y no está en enfriamiento. Los recursos bajos no lo ocultan.", "Wird nur angezeigt, solange nutzbar und ohne Abklingzeit. Zu wenig Ressourcen blenden es nicht aus.", "Affiché uniquement lorsqu'il est utilisable et hors recharge. Un manque de ressources ne le masque pas.", "Mostrato solo quando utilizzabile e non in recupero. Le risorse insufficienti non lo nascondono.", "Exibido apenas enquanto utilizável e fora de recarga. Poucos recursos não o ocultam.", "Показывается, только когда доступно и не на перезарядке. Нехватка ресурсов его не скрывает.", "사용 가능하고 재사용 대기 중이 아닐 때만 표시됩니다. 자원이 부족해도 숨기지 않습니다.", "仅在可用且不在冷却时显示。资源不足不会将其隐藏。", "僅在可用且不在冷卻時顯示。資源不足不會將其隱藏。" },
    ["Hidden (On CD)"] = { "Oculto (en CD)", "Verborgen (bei Abklingzeit)", "Masqué (en recharge)", "Nascosto (in recupero)", "Oculto (em recarga)", "Скрыт (на КД)", "숨김 (재사용 대기 중)", "隐藏（冷却中）", "隱藏（冷卻中）" },
    ["Hidden while on cooldown, preserving its slot."] = { "Oculto mientras está en enfriamiento, conservando su hueco.", "Verborgen während der Abklingzeit, der Platz bleibt erhalten.", "Masqué pendant la recharge, en conservant son emplacement.", "Nascosto durante il recupero, mantenendo la sua posizione.", "Oculto durante a recarga, preservando seu espaço.", "Скрыт, пока заклинание на перезарядке; место сохраняется.", "재사용 대기 중에는 숨기되 자리는 유지합니다.", "冷却期间隐藏，保留其位置。", "冷卻期間隱藏，保留其位置。" },
    ["Hidden (CD Ready)"] = { "Oculto (CD listo)", "Verborgen (Abklingzeit bereit)", "Masqué (recharge prête)", "Nascosto (recupero pronto)", "Oculto (recarga pronta)", "Скрыт (КД готов)", "숨김 (사용 가능)", "隐藏（冷却就绪）", "隱藏（冷卻就緒）" },
    ["Hidden while off cooldown, preserving its slot."] = { "Oculto mientras no está en enfriamiento, conservando su hueco.", "Verborgen ohne Abklingzeit, der Platz bleibt erhalten.", "Masqué hors recharge, en conservant son emplacement.", "Nascosto quando non è in recupero, mantenendo la sua posizione.", "Oculto fora de recarga, preservando seu espaço.", "Скрыт, когда заклинание не на перезарядке; место сохраняется.", "재사용 대기 중이 아닐 때 숨기되 자리는 유지합니다.", "不在冷却时隐藏，保留其位置。", "不在冷卻時隱藏，保留其位置。" },
    ["Hidden (Until Usable)"] = { "Oculto (hasta que sea usable)", "Verborgen (bis nutzbar)", "Masqué (jusqu'à utilisable)", "Nascosto (finché utilizzabile)", "Oculto (até ser utilizável)", "Скрыт (пока недоступно)", "숨김 (사용 가능해질 때까지)", "隐藏（可用前）", "隱藏（可用前）" },
    ["Glow (CD Ready)"] = { "Brillo (CD listo)", "Leuchten (Abklingzeit bereit)", "Lueur (recharge prête)", "Bagliore (recupero pronto)", "Brilho (recarga pronta)", "Свечение (КД готов)", "강조 효과 (사용 가능)", "发光（冷却就绪）", "發光（冷卻就緒）" },
    ["Glows while the spell is off cooldown."] = { "Brilla mientras el hechizo no está en enfriamiento.", "Leuchtet, solange der Zauber keine Abklingzeit hat.", "Brille tant que le sort n'est pas en recharge.", "Si illumina finché l'incantesimo non è in recupero.", "Brilha enquanto a magia está fora de recarga.", "Светится, пока заклинание не на перезарядке.", "주문이 재사용 대기 중이 아닐 때 빛납니다.", "法术不在冷却时发光。", "法術不在冷卻時發光。" },
    ["Glow (On CD)"] = { "Brillo (en CD)", "Leuchten (bei Abklingzeit)", "Lueur (en recharge)", "Bagliore (in recupero)", "Brilho (em recarga)", "Свечение (на КД)", "강조 효과 (재사용 대기 중)", "发光（冷却中）", "發光（冷卻中）" },
    ["Glows while the spell is on cooldown."] = { "Brilla mientras el hechizo está en enfriamiento.", "Leuchtet, solange der Zauber in der Abklingzeit ist.", "Brille tant que le sort est en recharge.", "Si illumina mentre l'incantesimo è in recupero.", "Brilha enquanto a magia está em recarga.", "Светится, пока заклинание на перезарядке.", "주문이 재사용 대기 중일 때 빛납니다.", "法术冷却期间发光。", "法術冷卻期間發光。" },
    ["Glow CD Ready (Resource Aware)"] = { "Brillo con CD listo (según recursos)", "Leuchten bei bereiter Abklingzeit (ressourcenabhängig)", "Lueur si prêt (selon les ressources)", "Bagliore se pronto (in base alle risorse)", "Brilho com recarga pronta (conforme recursos)", "Свечение при готовности (с учётом ресурсов)", "사용 가능 시 강조 (자원 고려)", "冷却就绪时发光（考虑资源）", "冷卻就緒時發光（考量資源）" },
    ["Glows only when off cooldown and current resources are sufficient."] = { "Brilla solo cuando no está en enfriamiento y los recursos actuales son suficientes.", "Leuchtet nur ohne Abklingzeit und bei ausreichenden Ressourcen.", "Brille uniquement hors recharge et avec des ressources suffisantes.", "Si illumina solo quando non è in recupero e le risorse attuali sono sufficienti.", "Brilha apenas fora de recarga e com recursos suficientes.", "Светится только когда нет перезарядки и ресурсов достаточно.", "재사용 대기 중이 아니고 현재 자원이 충분할 때만 빛납니다.", "仅在不在冷却且当前资源足够时发光。", "僅在不在冷卻且目前資源足夠時發光。" },
    ["Uses the bar's normal cooldown saturation."] = { "Usa la saturación de enfriamiento normal de la barra.", "Verwendet die normale Abklingzeit-Sättigung der Leiste.", "Utilise la saturation de recharge normale de la barre.", "Usa la normale saturazione del recupero della barra.", "Usa a saturação de recarga normal da barra.", "Использует обычную насыщенность перезарядки панели.", "바의 기본 재사용 대기 채도를 사용합니다.", "使用此条默认的冷却饱和度。", "使用此列預設的冷卻飽和度。" },
    ["Keep Colored (On CD)"] = { "Mantener color (en CD)", "Farbe behalten (bei Abklingzeit)", "Garder la couleur (en recharge)", "Mantieni colore (in recupero)", "Manter cor (em recarga)", "Сохранять цвет (на КД)", "색상 유지 (재사용 대기 중)", "保持彩色（冷却中）", "保持彩色（冷卻中）" },
