    ["Combo points restored to this theme's defaults."] = { "Puntos de combo restablecidos a los valores de este tema.", "Combopunkte auf die Standardwerte dieses Themas zurückgesetzt.", "Points de combo rétablis aux valeurs par défaut de ce thème.", "Punti combo ripristinati ai valori predefiniti di questo tema.", "Pontos de combo restaurados para os padrões deste tema.", "Приёмы в серии возвращены к значениям этой темы.", "연계 점수가 이 테마의 기본값으로 복원되었습니다.", "连击点已恢复为此主题的默认设置。", "連擊點已恢復為此主題的預設值。" },
    ["Apply %s and reload the interface?"] = { "¿Aplicar %s y recargar la interfaz?", "%s anwenden und die Oberfläche neu laden?", "Appliquer %s et recharger l'interface ?", "Applicare %s e ricaricare l'interfaccia?", "Aplicar %s e recarregar a interface?", "Применить %s и перезагрузить интерфейс?", "%s을(를) 적용하고 UI를 다시 불러올까요?", "应用 %s 并重新加载界面？", "套用 %s 並重新載入介面？" },
    ["Invalid profile."] = { "Perfil no válido.", "Ungültiges Profil.", "Profil invalide.", "Profilo non valido.", "Perfil inválido.", "Недопустимый профиль.", "잘못된 프로필입니다.", "无效的配置文件。", "無效的設定檔。" },
    ["Notice: this string uses the old format and does not say which variant (Retail or Forever) it came from. Check the result after reloading."] = { "Aviso: esta cadena usa el formato antiguo y no indica de qué variante (Retail o Forever) procede. Revisa el resultado tras recargar.", "Hinweis: Diese Zeichenkette nutzt das alte Format und gibt nicht an, aus welcher Variante (Retail oder Forever) sie stammt. Prüfe das Ergebnis nach dem Neuladen.", "Avis : cette chaîne utilise l'ancien format et n'indique pas de quelle variante (Retail ou Forever) elle provient. Vérifiez le résultat après le rechargement.", "Avviso: questa stringa usa il vecchio formato e non indica da quale variante (Retail o Forever) provenga. Controlla il risultato dopo il ricaricamento.", "Aviso: esta string usa o formato antigo e não indica de qual variante (Retail ou Forever) veio. Verifique o resultado após recarregar.", "Внимание: эта строка использует старый формат и не указывает, из какого варианта (Retail или Forever) она получена. Проверьте результат после перезагрузки.", "알림: 이 문자열은 이전 형식이며 어느 버전(Retail 또는 Forever)에서 왔는지 알 수 없습니다. UI를 다시 불러온 뒤 결과를 확인하세요.", "提示：此字符串使用旧格式，未标明来自哪个版本（Retail 或 Forever）。请在重新加载后检查结果。", "提示：此字串使用舊格式，未標明來自哪個版本（Retail 或 Forever）。請在重新載入後檢查結果。" },
    ["Profile string not recognized as a KullThranUI string."] = { "La cadena de perfil no se reconoce como de KullThranUI.", "Die Profilzeichenkette wird nicht als KullThranUI-Zeichenkette erkannt.", "Cette chaîne de profil n'est pas reconnue comme provenant de KullThranUI.", "La stringa del profilo non è riconosciuta come stringa di KullThranUI.", "A string de perfil não foi reconhecida como do KullThranUI.", "Строка профиля не распознана как строка KullThranUI.", "KullThranUI 프로필 문자열로 인식되지 않습니다.", "无法识别为 KullThranUI 的配置字符串。", "無法辨識為 KullThranUI 的設定字串。" },
    ["Unsupported profile version. Export the profile again from this variant."] = { "Versión de perfil no compatible. Vuelve a exportar el perfil desde esta variante.", "Nicht unterstützte Profilversion. Exportiere das Profil erneut aus dieser Variante.", "Version de profil non prise en charge. Exportez à nouveau le profil depuis cette variante.", "Versione del profilo non supportata. Esporta di nuovo il profilo da questa variante.", "Versão de perfil não suportada. Exporte o perfil novamente a partir desta variante.", "Неподдерживаемая версия профиля. Экспортируйте профиль заново из этого варианта.", "지원되지 않는 프로필 버전입니다. 이 버전에서 프로필을 다시 내보내세요.", "不支持的配置文件版本。请从此版本重新导出配置文件。", "不支援的設定檔版本。請從此版本重新匯出設定檔。" },
    ["Notice: this profile comes from the %s variant and is being imported into %s. It is usually compatible, but may cause incompatibilities."] = { "Aviso: este perfil procede de la variante %s y se está importando en %s. Normalmente es compatible, pero puede dar incompatibilidades.", "Hinweis: Dieses Profil stammt aus der Variante %s und wird in %s importiert. Meist ist es kompatibel, kann aber Unverträglichkeiten verursachen.", "Avis : ce profil provient de la variante %s et est importé dans %s. Il est généralement compatible, mais peut provoquer des incompatibilités.", "Avviso: questo profilo proviene dalla variante %s e viene importato in %s. Di solito è compatibile, ma può causare incompatibilità.", "Aviso: este perfil vem da variante %s e está sendo importado em %s. Normalmente é compatível, mas pode causar incompatibilidades.", "Внимание: этот профиль получен из варианта %s и импортируется в %s. Обычно он совместим, но возможны несовместимости.", "알림: 이 프로필은 %s 버전에서 왔으며 %s에 가져오는 중입니다. 대체로 호환되지만 문제가 생길 수 있습니다.", "提示：此配置文件来自 %s 版本，正导入到 %s。通常可以兼容，但可能出现不兼容的情况。", "提示：此設定檔來自 %s 版本，正匯入到 %s。通常可以相容，但可能出現不相容的情況。" },
    ["Nameplates mark enemies you still need for a quest with a yellow \"!\" in every style."] = { "Las placas de nombre marcan con un \"!\" amarillo a los enemigos que aún necesitas para una misión, en todos los estilos.", "Namensplaketten markieren Gegner, die du noch für eine Quest brauchst, in jedem Stil mit einem gelben „!“.", "Les plaques de nom marquent d'un « ! » jaune les ennemis dont vous avez encore besoin pour une quête, dans tous les styles.", "Le targhette segnano con un \"!\" giallo i nemici che ti servono ancora per una missione, in tutti gli stili.", "As placas de nome marcam com um \"!\" amarelo os inimigos de que você ainda precisa para uma missão, em todos os estilos.", "Индикаторы здоровья отмечают жёлтым «!» врагов, которые всё ещё нужны для задания, во всех стилях.", "아직 퀘스트에 필요한 적에게 모든 스타일에서 노란 \"!\"가 표시됩니다.", "所有样式下，姓名板都会用黄色“!”标出你仍需击杀的任务敌人。", "所有樣式下，名條都會用黃色「!」標出你仍需擊殺的任務敵人。" },
    ["The nameplate live preview shows the selected visual style."] = { "La vista previa en vivo de las placas de nombre muestra el estilo visual seleccionado.", "Die Live-Vorschau der Namensplaketten zeigt den gewählten visuellen Stil.", "L'aperçu en direct des plaques de nom affiche le style visuel sélectionné.", "L'anteprima dal vivo delle targhette mostra lo stile visivo selezionato.", "A pré-visualização ao vivo das placas de nome mostra o estilo visual selecionado.", "Предпросмотр индикаторов здоровья показывает выбранный визуальный стиль.", "이름표 실시간 미리보기에 선택한 시각 스타일이 표시됩니다.", "姓名板实时预览会显示当前选择的视觉样式。", "名條即時預覽會顯示目前選擇的視覺樣式。" },
    ["3D portraits in circular Unit Frame portraits."] = { "Retratos 3D en los retratos circulares de los marcos de unidad.", "3D-Porträts in runden Einheitenfenster-Porträts.", "Portraits 3D dans les portraits circulaires des cadres d'unité.", "Ritratti 3D nei ritratti circolari dei riquadri unità.", "Retratos 3D nos retratos circulares dos quadros de unidade.", "3D-портреты в круглых портретах рамок бойцов.", "원형 개체창 초상화에 3D 초상화를 지원합니다.", "单位框体的圆形头像现在支持 3D 头像。", "單位框架的圓形頭像現在支援 3D 頭像。" },
    ["Chat: left-click a channel tag to start typing in that channel."] = { "Chat: haz clic izquierdo en la etiqueta de un canal para empezar a escribir en él.", "Chat: Linksklick auf ein Kanal-Kürzel, um direkt in diesem Kanal zu schreiben.", "Chat : clic gauche sur l'étiquette d'un canal pour commencer à y écrire.", "Chat: clic sinistro sull'etichetta di un canale per iniziare a scrivere in quel canale.", "Chat: clique com o botão esquerdo na etiqueta de um canal para começar a escrever nele.", "Чат: щёлкните левой кнопкой по метке канала, чтобы начать писать в этом канале.", "채팅: 채널 태그를 좌클릭하면 해당 채널로 바로 입력할 수 있습니다.", "聊天：左键点击频道标签即可直接在该频道发言。", "聊天：左鍵點擊頻道標籤即可直接在該頻道發言。" },
    ["Redesigned Mail skin."] = { "Skin del correo rediseñado.", "Überarbeitetes Post-Design.", "Habillage du courrier remanié.", "Skin della posta ridisegnato.", "Skin do correio redesenhado.", "Переработан внешний вид почты.", "우편함 스킨을 새로 디자인했습니다.", "重新设计了邮件界面皮肤。", "重新設計了郵件介面外觀。" },
    ["KUI no longer changes your UI scale unless you choose a scale yourself, and module on/off toggles apply correctly."] = { "KUI ya no cambia la escala de tu interfaz salvo que elijas una escala tú mismo, y los interruptores de activar/desactivar módulos se aplican correctamente.", "KUI ändert deine UI-Skalierung nicht mehr, außer du wählst selbst eine Skalierung, und die Modulschalter greifen korrekt.", "KUI ne modifie plus l'échelle de l'interface sauf si vous en choisissez une vous-même, et les interrupteurs d'activation des modules s'appliquent correctement.", "KUI non modifica più la scala dell'interfaccia a meno che tu non ne scelga una, e gli interruttori di attivazione dei moduli vengono applicati correttamente.", "O KUI não altera mais a escala da sua interface, a menos que você escolha uma escala, e os botões de ativar/desativar módulos são aplicados corretamente.", "KUI больше не меняет масштаб интерфейса, пока вы сами не выберете масштаб, а переключатели модулей применяются корректно.", "KUI는 직접 크기를 선택하지 않는 한 UI 크기를 바꾸지 않으며, 모듈 켜기/끄기가 올바르게 적용됩니다.", "除非你自己选择缩放，否则 KUI 不再更改界面缩放；模块开关也能正确生效。", "除非你自己選擇縮放，否則 KUI 不再變更介面縮放；模組開關也能正確生效。" },
    ["Fixed KUI Tracker icons briefly showing a green swipe."] = { "Corregido que los iconos del KUI Tracker mostraran brevemente una animación verde.", "Behoben: KUI-Tracker-Symbole zeigten kurzzeitig eine grüne Abklinganimation.", "Correction : les icônes du KUI Tracker affichaient brièvement une animation verte.", "Corretto: le icone del KUI Tracker mostravano brevemente un'animazione verde.", "Corrigido: os ícones do KUI Tracker exibiam brevemente uma animação verde.", "Исправлено: значки KUI Tracker ненадолго показывали зелёную анимацию.", "KUI Tracker 아이콘에 녹색 애니메이션이 잠깐 보이던 문제를 수정했습니다.", "修复了 KUI Tracker 图标短暂显示绿色扫描动画的问题。", "修復了 KUI Tracker 圖示短暫顯示綠色掃描動畫的問題。" },
    ["Profile import notices, nameplate style prompts and visual style messages are now available in every supported language."] = { "Los avisos de importación de perfiles, los mensajes de estilo de las placas de nombre y los mensajes de estilo visual ya están disponibles en todos los idiomas compatibles.", "Hinweise beim Profilimport, Abfragen zum Namensplaketten-Stil und Meldungen zum visuellen Stil sind jetzt in allen unterstützten Sprachen verfügbar.", "Les avis d'importation de profil, les invites de style des plaques de nom et les messages de style visuel sont désormais disponibles dans toutes les langues prises en charge.", "Gli avvisi di importazione del profilo, le richieste sullo stile delle targhette e i messaggi sullo stile visivo sono ora disponibili in tutte le lingue supportate.", "Os avisos de importação de perfil, as mensagens de estilo das placas de nome e as mensagens de estilo visual agora estão disponíveis em todos os idiomas suportados.", "Уведомления при импорте профиля, запросы стиля индикаторов здоровья и сообщения о визуальном стиле теперь доступны на всех поддерживаемых языках.", "프로필 가져오기 알림, 이름표 스타일 안내, 시각 스타일 메시지가 지원하는 모든 언어로 제공됩니다.", "配置文件导入提示、姓名板样式提示和视觉样式消息现已支持所有受支持的语言。", "設定檔匯入提示、名條樣式提示和視覺樣式訊息現已支援所有受支援的語言。" },
    ["New Visual Style selector (KUI, Classic, Retail, Forever) in the General tab and in the Installer. Applying a style restyles Unit Frames, Party Frames, Nameplates, Action Bars, Resource Bars, Cast Bar, Cooldown Manager, Minimap and Skins together, shows a live preview and reloads the interface."] = { "Nuevo selector de estilo visual (KUI, Classic, Retail, Forever) en la pestaña General y en el instalador. Al aplicar un estilo se rediseñan a la vez los marcos de unidad, marcos de grupo, placas de nombre, barras de acción, barras de recursos, barra de lanzamiento, Cooldown Manager, minimapa y skins, con vista previa en vivo y recarga de la interfaz.", "Neue Auswahl des visuellen Stils (KUI, Classic, Retail, Forever) im Reiter Allgemein und im Installer. Beim Anwenden eines Stils werden Einheitenfenster, Gruppenfenster, Namensplaketten, Aktionsleisten, Ressourcenleisten, Zauberleiste, Cooldown Manager, Minikarte und Skins gemeinsam umgestaltet; mit Live-Vorschau und Neuladen der Oberfläche.", "Nouveau sélecteur de style visuel (KUI, Classic, Retail, Forever) dans l'onglet Général et dans l'installateur. Appliquer un style remodèle ensemble les cadres d'unité, cadres de groupe, plaques de nom, barres d'action, barres de ressources, barre d'incantation, Cooldown Manager, minicarte et habillages, avec aperçu en direct et rechargement de l'interface.", "Nuovo selettore dello stile visivo (KUI, Classic, Retail, Forever) nella scheda Generale e nell'installer. Applicare uno stile ridisegna insieme riquadri unità, riquadri gruppo, targhette, barre azioni, barre risorse, barra di lancio, Cooldown Manager, minimappa e skin, con anteprima dal vivo e ricaricamento dell'interfaccia.", "Novo seletor de estilo visual (KUI, Classic, Retail, Forever) na aba Geral e no instalador. Aplicar um estilo redesenha juntos os quadros de unidade, quadros de grupo, placas de nome, barras de ação, barras de recursos, barra de lançamento, Cooldown Manager, minimapa e skins, com pré-visualização ao vivo e recarga da interface.", "Новый выбор визуального стиля (KUI, Classic, Retail, Forever) на вкладке «Общее» и в установщике. Применение стиля одновременно меняет рамки бойцов, рамки группы, индикаторы здоровья, панели действий, панели ресурсов, полосу заклинаний, Cooldown Manager, миникарту и оформление окон; есть живой предпросмотр, интерфейс перезагружается.", "일반 탭과 설치 도우미에 시각 스타일 선택(KUI, Classic, Retail, Forever)이 추가되었습니다. 스타일을 적용하면 개체창, 파티 창, 이름표, 행동 단축바, 자원 바, 시전 바, Cooldown Manager, 미니맵, 스킨이 함께 바뀌며 실시간 미리보기가 제공되고 UI가 다시 불러와집니다.", "“常规”标签页和安装向导新增视觉风格选择（KUI、Classic、Retail、Forever）。应用风格会同时更换单位框体、小队框体、姓名板、动作条、资源条、施法条、Cooldown Manager、小地图和界面皮肤，提供实时预览并重新加载界面。", "「一般」分頁和安裝精靈新增視覺風格選擇（KUI、Classic、Retail、Forever）。套用風格會同時更換單位框架、隊伍框架、名條、快捷列、資源條、施法條、Cooldown Manager、小地圖和介面外觀，提供即時預覽並重新載入介面。" },
    ["The Installer's color step is now Visual Style & Color and returns to that page after the reload."] = { "El paso de color del instalador es ahora Estilo visual y color, y vuelve a esa página tras la recarga.", "Der Farbschritt des Installers heißt jetzt „Visueller Stil & Farbe“ und kehrt nach dem Neuladen zu dieser Seite zurück.", "L'étape de couleur de l'installateur devient « Style visuel et couleur » et revient sur cette page après le rechargement.", "Il passaggio colore dell'installer ora si chiama Stile visivo e colore e torna a quella pagina dopo il ricaricamento.", "A etapa de cor do instalador agora se chama Estilo visual e cor e volta a essa página após a recarga.", "Шаг установщика с цветом теперь называется «Визуальный стиль и цвет» и после перезагрузки возвращается на эту страницу.", "설치 도우미의 색상 단계가 시각 스타일 및 색상으로 바뀌었고, 다시 불러온 뒤 같은 페이지로 돌아옵니다.", "安装向导的颜色步骤现为“视觉风格与颜色”，重新加载后会返回该页面。", "安裝精靈的顏色步驟現為「視覺風格與顏色」，重新載入後會返回該頁面。" },
    ["Nameplates: style presets in Nameplates > General with a preview of each. Classic has the original bronze border, a gold level pill and larger bars; Retail uses Blizzard's own nameplate art with the level inside the bar; Forever has taller bars with the name above, a bronze border and the level in a yellow box beside the bar."] = { "Placas de nombre: estilos predefinidos en Placas de nombre > General, con vista previa de cada uno. Classic tiene el borde de bronce original, una pastilla dorada para el nivel y barras más grandes; Retail usa el arte propio de Blizzard con el nivel dentro de la barra; Forever tiene barras más altas con el nombre encima, borde de bronce y el nivel en una caja amarilla junto a la barra.", "Namensplaketten: Stilvorgaben unter Namensplaketten > Allgemein mit Vorschau für jede. Classic hat den originalen Bronzerahmen, eine goldene Stufenkapsel und größere Leisten; Retail nutzt Blizzards eigene Plaketten-Grafik mit der Stufe in der Leiste; Forever hat höhere Leisten mit dem Namen darüber, Bronzerahmen und die Stufe in einem gelben Kasten neben der Leiste.", "Plaques de nom : styles prédéfinis dans Plaques de nom > Général, avec un aperçu de chacun. Classic a la bordure bronze d'origine, une pastille dorée pour le niveau et des barres plus grandes ; Retail utilise les visuels de plaques de Blizzard avec le niveau dans la barre ; Forever a des barres plus hautes avec le nom au-dessus, une bordure bronze et le niveau dans un encadré jaune à côté de la barre.", "Targhette: stili predefiniti in Targhette > Generale, con anteprima di ciascuno. Classic ha il bordo bronzo originale, una pillola dorata per il livello e barre più grandi; Retail usa la grafica delle targhette di Blizzard con il livello dentro la barra; Forever ha barre più alte con il nome sopra, bordo bronzo e il livello in un riquadro giallo accanto alla barra.", "Placas de nome: estilos predefinidos em Placas de nome > Geral, com pré-visualização de cada um. Classic tem a borda de bronze original, uma pílula dourada para o nível e barras maiores; Retail usa a arte de placas da própria Blizzard com o nível dentro da barra; Forever tem barras mais altas com o nome acima, borda de bronze e o nível em uma caixa amarela ao lado da barra.", "Индикаторы здоровья: пресеты стилей в разделе «Индикаторы здоровья» > «Общее» с предпросмотром каждого. У Classic — оригинальная бронзовая рамка, золотая плашка уровня и более крупные полосы; Retail использует оформление Blizzard с уровнем внутри полосы; у Forever более высокие полосы с именем сверху, бронзовая рамка и уровень в жёлтом блоке рядом с полосой.", "이름표: 이름표 > 일반에 스타일 프리셋이 추가되었고 각각 미리보기가 제공됩니다. Classic은 원래의 청동 테두리, 금색 레벨 알약, 더 큰 바를 사용하고, Retail은 블리자드 고유의 이름표 아트와 바 안의 레벨을 사용하며, Forever는 이름이 위에 있는 더 높은 바, 청동 테두리, 바 옆의 노란 레벨 상자를 사용합니다.", "姓名板：在“姓名板 > 常规”中新增样式预设，并提供各自的预览。Classic 使用原版青铜边框、金色等级胶囊和更大的血条；Retail 使用暴雪自带的姓名板素材，等级显示在血条内；Forever 的血条更高，名称在上方，带青铜边框，等级显示在血条旁的黄色方框中。", "名條：在「名條 > 一般」中新增樣式預設，並提供各自的預覽。Classic 使用原版青銅邊框、金色等級膠囊和更大的血條；Retail 使用暴雪內建的名條素材，等級顯示在血條內；Forever 的血條更高，名稱在上方，帶青銅邊框，等級顯示在血條旁的黃色方框中。" },
    ["Unit Frames: authentic player, target and pet frame art per style, Blizzard-style name and level text, combat and resting icons, a frame-size option, and Rare/Elite indicators."] = { "Marcos de unidad: arte auténtico de los marcos de jugador, objetivo y mascota para cada estilo, texto de nombre y nivel al estilo Blizzard, iconos de combate y descanso, opción de tamaño del marco e indicadores de Raro/Élite.", "Einheitenfenster: authentische Grafiken für Spieler-, Ziel- und Begleiterfenster je Stil, Name und Stufe im Blizzard-Stil, Kampf- und Ruhesymbole, eine Option für die Fenstergröße sowie Selten-/Elite-Anzeigen.", "Cadres d'unité : visuels authentiques des cadres du joueur, de la cible et du familier pour chaque style, texte de nom et de niveau à la manière de Blizzard, icônes de combat et de repos, option de taille du cadre et indicateurs Rare/Élite.", "Riquadri unità: grafica autentica dei riquadri giocatore, bersaglio e animale per ogni stile, testo di nome e livello in stile Blizzard, icone di combattimento e riposo, opzione per la dimensione del riquadro e indicatori Raro/Élite.", "Quadros de unidade: arte autêntica dos quadros de jogador, alvo e mascote para cada estilo, texto de nome e nível no estilo Blizzard, ícones de combate e descanso, opção de tamanho do quadro e indicadores de Raro/Elite.", "Рамки бойцов: оригинальное оформление рамок игрока, цели и питомца для каждого стиля, текст имени и уровня в стиле Blizzard, значки боя и отдыха, параметр размера рамки и индикаторы редких/элитных.", "개체창: 스타일별 정통 플레이어·대상·소환수 창 아트, 블리자드 스타일 이름 및 레벨 텍스트, 전투 및 휴식 아이콘, 창 크기 옵션, 희귀/엘리트 표시기.", "单位框体：每种样式都有原版风格的玩家、目标和宠物框体素材，暴雪风格的名称与等级文字，战斗和休息图标，框体大小选项，以及稀有/精英标记。", "單位框架：每種樣式都有原版風格的玩家、目標和寵物框架素材，暴雪風格的名稱與等級文字，戰鬥和休息圖示，框架大小選項，以及稀有/精英標記。" },
    ["Combo points under the Player and Target frames can be Off, Modern or Classic (Target also has a portrait ring), as circles or pips, placed below or above the frame with X/Y offsets. Each style picks its own look by default."] = { "Los puntos de combo bajo los marcos de jugador y objetivo pueden ser Desactivado, Moderno o Clásico (el objetivo también tiene un anillo de retrato), como círculos o segmentos, debajo o encima del marco con desplazamientos X/Y. Cada estilo elige su propio aspecto por defecto.", "Combopunkte unter dem Spieler- und Zielfenster können Aus, Modern oder Klassisch sein (das Ziel hat zusätzlich einen Porträtring), als Kreise oder Segmente, unter oder über dem Fenster mit X/Y-Versatz. Jeder Stil wählt standardmäßig sein eigenes Aussehen.", "Les points de combo sous les cadres du joueur et de la cible peuvent être Désactivés, Modernes ou Classiques (la cible a aussi un anneau de portrait), en cercles ou en segments, placés sous ou au-dessus du cadre avec des décalages X/Y. Chaque style choisit son propre aspect par défaut.", "I punti combo sotto i riquadri giocatore e bersaglio possono essere Disattivati, Moderni o Classici (il bersaglio ha anche un anello del ritratto), come cerchi o segmenti, sotto o sopra il riquadro con offset X/Y. Ogni stile sceglie di default il proprio aspetto.", "Os pontos de combo sob os quadros de jogador e alvo podem ser Desativados, Modernos ou Clássicos (o alvo também tem um anel de retrato), como círculos ou segmentos, abaixo ou acima do quadro com deslocamentos X/Y. Cada estilo escolhe seu próprio visual por padrão.", "Приёмы в серии под рамками игрока и цели могут быть выключены, современными или классическими (у цели есть ещё кольцо портрета), в виде кругов или сегментов, под рамкой или над ней, со смещением X/Y. По умолчанию каждый стиль выбирает свой вид.", "플레이어 및 대상 창 아래의 연계 점수를 끔, 모던, 클래식(대상은 초상화 링도 가능)으로 선택할 수 있으며, 원형 또는 막대 형태로 창 아래나 위에 X/Y 오프셋과 함께 배치할 수 있습니다. 각 스타일은 기본으로 자신만의 모양을 사용합니다.", "玩家和目标框体下方的连击点可选择关闭、现代或经典（目标还有头像环），可用圆形或条形，放在框体下方或上方并可设置 X/Y 偏移。每种样式默认使用自己的外观。", "玩家和目標框架下方的連擊點可選擇關閉、現代或經典（目標還有頭像環），可用圓形或條形，放在框架下方或上方並可設定 X/Y 偏移。每種樣式預設使用自己的外觀。" },
    ["Incoming heal prediction, combat text on the portrait (with an off toggle and a white-numbers option) and an aggro glow toggle that also lights the Target portrait overlays."] = { "Predicción de curación entrante, texto de combate sobre el retrato (con interruptor para desactivarlo y opción de números blancos) e interruptor del brillo de amenaza, que también ilumina las superposiciones del retrato del objetivo.", "Vorhersage eingehender Heilung, Kampftext auf dem Porträt (abschaltbar, mit Option für weiße Zahlen) und ein Schalter für das Aggro-Leuchten, das auch die Porträt-Überlagerungen des Ziels aufleuchten lässt.", "Prévision des soins entrants, texte de combat sur le portrait (désactivable, avec option de chiffres blancs) et option de lueur d'aggro, qui éclaire aussi les surcouches du portrait de la cible.", "Previsione delle cure in arrivo, testo di combattimento sul ritratto (disattivabile, con opzione per i numeri bianchi) e un interruttore per il bagliore di aggro, che illumina anche le sovrapposizioni del ritratto del bersaglio.", "Previsão de cura recebida, texto de combate sobre o retrato (com opção de desativar e de números brancos) e um botão para o brilho de aggro, que também ilumina as sobreposições do retrato do alvo.", "Прогноз входящего исцеления, боевой текст на портрете (можно отключить, есть вариант с белыми цифрами) и переключатель свечения агро, которое также подсвечивает наложения портрета цели.", "들어오는 치유 예측, 초상화 위 전투 텍스트(끄기 옵션과 흰색 숫자 옵션 포함), 그리고 대상 초상화 효과도 밝혀 주는 어그로 강조 효과 토글이 추가되었습니다.", "新增即将到来的治疗预测、头像上的战斗文字（可关闭，并有白色数字选项），以及仇恨发光开关，它也会点亮目标头像的叠加层。", "新增即將到來的治療預測、頭像上的戰鬥文字（可關閉，並有白色數字選項），以及仇恨發光開關，它也會點亮目標頭像的疊加層。" },
    ["Party Frames: portraits can be 2D, 3D or Class Theme, with zoom, rotation, offset, side, facing and border options."] = { "Marcos de grupo: los retratos pueden ser 2D, 3D o Tema de clase, con opciones de zoom, rotación, desplazamiento, lado, orientación y borde.", "Gruppenfenster: Porträts können 2D, 3D oder Klassenthema sein, mit Optionen für Zoom, Rotation, Versatz, Seite, Blickrichtung und Rahmen.", "Cadres de groupe : les portraits peuvent être 2D, 3D ou Thème de classe, avec des options de zoom, rotation, décalage, côté, orientation et bordure.", "Riquadri gruppo: i ritratti possono essere 2D, 3D o Tema di classe, con opzioni di zoom, rotazione, offset, lato, orientamento e bordo.", "Quadros de grupo: os retratos podem ser 2D, 3D ou Tema da classe, com opções de zoom, rotação, deslocamento, lado, direção e borda.", "Рамки группы: портреты могут быть 2D, 3D или в теме класса; доступны масштаб, поворот, смещение, сторона, направление взгляда и рамка.", "파티 창: 초상화를 2D, 3D, 직업 테마로 선택할 수 있으며 확대, 회전, 오프셋, 위치, 방향, 테두리 옵션이 있습니다.", "小队框体：头像可选 2D、3D 或职业主题，并提供缩放、旋转、偏移、位置、朝向和边框选项。", "隊伍框架：頭像可選 2D、3D 或職業主題，並提供縮放、旋轉、偏移、位置、朝向和邊框選項。" },
    ["Action Bars: Action Bar Art selector with live previews (Forever or Classic end caps); cooldown swipes follow the button shape."] = { "Barras de acción: selector de arte de la barra de acción con vistas previas en vivo (remates Forever o Classic); las animaciones de enfriamiento siguen la forma del botón.", "Aktionsleisten: Auswahl der Leistengrafik mit Live-Vorschau (Forever- oder Classic-Endkappen); Abklinganimationen folgen der Form der Schaltfläche.", "Barres d'action : sélecteur de décor avec aperçus en direct (ornements Forever ou Classic) ; les animations de recharge suivent la forme du bouton.", "Barre azioni: selettore della grafica con anteprime dal vivo (decorazioni Forever o Classic); le animazioni di recupero seguono la forma del pulsante.", "Barras de ação: seletor de arte da barra com pré-visualizações ao vivo (ornamentos Forever ou Classic); as animações de recarga seguem o formato do botão.", "Панели действий: выбор оформления панели с живым предпросмотром (украшения Forever или Classic); анимация перезарядки повторяет форму кнопки.", "행동 단축바: 실시간 미리보기가 있는 단축바 장식 선택(Forever 또는 Classic 장식)과 버튼 모양을 따르는 재사용 대기 애니메이션.", "动作条：新增带实时预览的动作条装饰选择（Forever 或 Classic 风格），冷却扫描动画会跟随按钮形状。", "快捷列：新增帶即時預覽的快捷列裝飾選擇（Forever 或 Classic 風格），冷卻掃描動畫會跟隨按鈕形狀。" },
    ["Cooldown Manager: per-ability visibility rules (right-click an icon) such as hidden or glowing while on cooldown, usable-only display and charge controls; the KUI Tracker adapts to every style."] = { "Cooldown Manager: reglas de visibilidad por habilidad (clic derecho en un icono), como ocultar o resaltar durante el enfriamiento, mostrar solo si es usable y controles de cargas; el KUI Tracker se adapta a todos los estilos.", "Cooldown Manager: Sichtbarkeitsregeln pro Fähigkeit (Rechtsklick auf ein Symbol), z. B. verborgen oder leuchtend während der Abklingzeit, Anzeige nur bei Nutzbarkeit und Aufladungs-Optionen; der KUI Tracker passt sich jedem Stil an.", "Cooldown Manager : règles de visibilité par capacité (clic droit sur une icône), comme masquer ou faire briller pendant la recharge, affichage uniquement si utilisable et options de charges ; le KUI Tracker s'adapte à chaque style.", "Cooldown Manager: regole di visibilità per abilità (clic destro su un'icona), come nascosta o luminosa durante il recupero, visualizzazione solo se utilizzabile e controlli per le cariche; il KUI Tracker si adatta a ogni stile.", "Cooldown Manager: regras de visibilidade por habilidade (clique direito em um ícone), como ocultar ou brilhar durante a recarga, exibir apenas se utilizável e controles de cargas; o KUI Tracker se adapta a cada estilo.", "Cooldown Manager: правила видимости для каждой способности (ПКМ по значку), например скрытие или свечение на перезарядке, показ только когда доступно, управление зарядами; KUI Tracker подстраивается под каждый стиль.", "Cooldown Manager: 능력별 표시 규칙(아이콘 우클릭) — 재사용 대기 중 숨김 또는 강조, 사용 가능할 때만 표시, 충전 관련 설정. KUI Tracker가 모든 스타일에 맞춰집니다.", "Cooldown Manager：可为每个技能设置可见性规则（右键点击图标），例如冷却时隐藏或发光、仅在可用时显示，以及充能相关选项；KUI Tracker 会适配每种样式。", "Cooldown Manager：可為每個技能設定可見性規則（右鍵點擊圖示），例如冷卻時隱藏或發光、僅在可用時顯示，以及充能相關選項；KUI Tracker 會適配每種樣式。" },
    ["Minimap: frame rings per style with a selector and Live Preview."] = { "Minimapa: marcos circulares por estilo con selector y vista previa en vivo.", "Minikarte: Rahmenringe je Stil mit Auswahl und Live-Vorschau.", "Minicarte : anneaux de cadre par style avec sélecteur et aperçu en direct.", "Minimappa: anelli della cornice per stile con selettore e anteprima dal vivo.", "Minimapa: anéis de moldura por estilo, com seletor e pré-visualização ao vivo.", "Миникарта: рамки-кольца для каждого стиля с выбором и живым предпросмотром.", "미니맵: 스타일별 테두리 링을 선택기와 실시간 미리보기로 제공합니다.", "小地图：每种样式都有对应的边框环，带选择器和实时预览。", "小地圖：每種樣式都有對應的邊框環，附選擇器與即時預覽。" },
    ["The Objective Tracker headers show an accent-colored gradient bar in the Blizzard-art styles."] = { "Las cabeceras del rastreador de objetivos muestran una barra degradada con el color de acento en los estilos con arte de Blizzard.", "Die Überschriften der Zielverfolgung zeigen in den Blizzard-Grafikstilen einen Farbverlaufsbalken in der Akzentfarbe.", "Les en-têtes du suivi d'objectifs affichent une barre dégradée aux couleurs de l'accent dans les styles à visuels Blizzard.", "Le intestazioni del tracker obiettivi mostrano una barra sfumata nel colore d'accento negli stili con grafica Blizzard.", "Os cabeçalhos do rastreador de objetivos exibem uma barra em degradê com a cor de destaque nos estilos com arte da Blizzard.", "Заголовки списка заданий показывают градиентную полосу акцентного цвета в стилях с оформлением Blizzard.", "퀘스트 추적기 머리글에 블리자드 아트 스타일에서 강조색 그라데이션 바가 표시됩니다.", "在使用暴雪素材的样式中，任务追踪器标题会显示强调色渐变条。", "在使用暴雪素材的樣式中，任務追蹤器標題會顯示強調色漸層條。" },
    ["Profiles remember whether they come from Retail or Forever; importing a string from the other variant works with a notice, and UI scale is no longer part of exported or imported profiles."] = { "Los perfiles recuerdan si proceden de Retail o Forever; importar una cadena de la otra variante funciona con un aviso, y la escala de la interfaz ya no forma parte de los perfiles exportados ni importados.", "Profile merken sich, ob sie aus Retail oder Forever stammen; der Import einer Zeichenkette der anderen Variante funktioniert mit einem Hinweis, und die UI-Skalierung ist nicht mehr Teil exportierter oder importierter Profile.", "Les profils retiennent s'ils viennent de Retail ou de Forever ; importer une chaîne de l'autre variante fonctionne avec un avis, et l'échelle de l'interface ne fait plus partie des profils exportés ou importés.", "I profili ricordano se provengono da Retail o Forever; importare una stringa dell'altra variante funziona con un avviso, e la scala dell'interfaccia non fa più parte dei profili esportati o importati.", "Os perfis lembram se vêm do Retail ou do Forever; importar uma string da outra variante funciona com um aviso, e a escala da interface não faz mais parte dos perfis exportados ou importados.", "Профили запоминают, из Retail они или из Forever; импорт строки из другого варианта работает с уведомлением, а масштаб интерфейса больше не входит в экспортируемые и импортируемые профили.", "프로필이 Retail과 Forever 중 어느 쪽에서 왔는지 기억하며, 다른 버전의 문자열도 알림과 함께 가져올 수 있습니다. UI 크기는 더 이상 내보내기/가져오기 프로필에 포함되지 않습니다.", "配置文件会记录来自 Retail 还是 Forever；导入另一版本的字符串时会给出提示并正常导入，界面缩放也不再包含在导出或导入的配置文件中。", "設定檔會記錄來自 Retail 還是 Forever；匯入另一版本的字串時會給出提示並正常匯入，介面縮放也不再包含在匯出或匯入的設定檔中。" },
    ["The changelog button now sits in the General tab header."] = { "El botón del registro de cambios ahora está en la cabecera de la pestaña General.", "Der Changelog-Button befindet sich jetzt in der Kopfzeile des Reiters Allgemein.", "Le bouton du journal des modifications se trouve désormais dans l'en-tête de l'onglet Général.", "Il pulsante del changelog si trova ora nell'intestazione della scheda Generale.", "O botão do registro de alterações agora fica no cabeçalho da aba Geral.", "Кнопка списка изменений теперь находится в заголовке вкладки «Общее».", "변경 내역 버튼이 일반 탭 머리글로 옮겨졌습니다.", "更新日志按钮现在位于“常规”标签页的标题栏中。", "更新日誌按鈕現在位於「一般」分頁的標題列中。" },
    ["Party Frames: Portrait Mode (2D, 3D or Class Theme) with 3D Portrait Zoom, Rotation and X/Y Offset sliders."] = { "Marcos de grupo: Modo de retrato (2D, 3D o Tema de clase) con controles deslizantes de zoom, rotación y desplazamiento X/Y del retrato 3D.", "Gruppenfenster: Porträtmodus (2D, 3D oder Klassenthema) mit Reglern für Zoom, Rotation und X/Y-Versatz des 3D-Porträts.", "Cadres de groupe : mode de portrait (2D, 3D ou Thème de classe) avec curseurs de zoom, rotation et décalage X/Y du portrait 3D.", "Riquadri gruppo: modalità ritratto (2D, 3D o Tema di classe) con cursori per zoom, rotazione e offset X/Y del ritratto 3D.", "Quadros de grupo: modo de retrato (2D, 3D ou Tema da classe) com controles deslizantes de zoom, rotação e deslocamento X/Y do retrato 3D.", "Рамки группы: режим портрета (2D, 3D или тема класса) с ползунками масштаба, поворота и смещения X/Y для 3D-портрета.", "파티 창: 초상화 모드(2D, 3D, 직업 테마)와 3D 초상화 확대, 회전, X/Y 오프셋 슬라이더.", "小队框体：头像模式（2D、3D 或职业主题），并提供 3D 头像的缩放、旋转和 X/Y 偏移滑块。", "隊伍框架：頭像模式（2D、3D 或職業主題），並提供 3D 頭像的縮放、旋轉和 X/Y 偏移滑桿。" },
    ["Chat: new \"Click Channel to Chat\" option; left-click a channel tag to start typing in that channel."] = { "Chat: nueva opción «Clic en canal para chatear»; haz clic izquierdo en la etiqueta de un canal para empezar a escribir en él.", "Chat: neue Option „Kanal anklicken, um zu schreiben“; Linksklick auf ein Kanal-Kürzel, um direkt in diesem Kanal zu schreiben.", "Chat : nouvelle option « Cliquer sur le canal pour écrire » ; clic gauche sur l'étiquette d'un canal pour commencer à y écrire.", "Chat: nuova opzione «Clic sul canale per scrivere»; clic sinistro sull'etichetta di un canale per iniziare a scrivere in quel canale.", "Chat: nova opção \"Clicar no canal para conversar\"; clique com o botão esquerdo na etiqueta de um canal para começar a escrever nele.", "Чат: новая опция «Клик по каналу для ввода»; щёлкните левой кнопкой по метке канала, чтобы начать писать в этом канале.", "채팅: \"채널 클릭으로 채팅 입력\" 옵션이 추가되었습니다. 채널 태그를 좌클릭하면 해당 채널로 바로 입력할 수 있습니다.", "聊天：新增“点击频道开始输入”选项；左键点击频道标签即可直接在该频道发言。", "聊天：新增「點擊頻道開始輸入」選項；左鍵點擊頻道標籤即可直接在該頻道發言。" },
    ["General: new \"KUI controls the UI scale\" option."] = { "General: nueva opción «KUI controla la escala de la interfaz».", "Allgemein: neue Option „KUI steuert die UI-Skalierung“.", "Général : nouvelle option « KUI contrôle l'échelle de l'interface ».", "Generale: nuova opzione «KUI controlla la scala dell'interfaccia».", "Geral: nova opção \"KUI controla a escala da interface\".", "Общее: новая опция «KUI управляет масштабом интерфейса».", "일반: \"KUI가 UI 크기를 조절\" 옵션이 추가되었습니다.", "常规：新增“由 KUI 控制界面缩放”选项。", "一般：新增「由 KUI 控制介面縮放」選項。" },
    ["Unit Frames: Blizzard-style name and level text, combat and resting icons, and a combo point ring on the Target frame."] = { "Marcos de unidad: texto de nombre y nivel al estilo Blizzard, iconos de combate y descanso, y un anillo de puntos de combo en el marco del objetivo.", "Einheitenfenster: Name und Stufe im Blizzard-Stil, Kampf- und Ruhesymbole sowie ein Combopunkt-Ring am Zielfenster.", "Cadres d'unité : texte de nom et de niveau à la manière de Blizzard, icônes de combat et de repos, et anneau de points de combo sur le cadre de la cible.", "Riquadri unità: testo di nome e livello in stile Blizzard, icone di combattimento e riposo e un anello di punti combo sul riquadro del bersaglio.", "Quadros de unidade: texto de nome e nível no estilo Blizzard, ícones de combate e descanso e um anel de pontos de combo no quadro do alvo.", "Рамки бойцов: текст имени и уровня в стиле Blizzard, значки боя и отдыха и кольцо приёмов в серии на рамке цели.", "개체창: 블리자드 스타일 이름 및 레벨 텍스트, 전투 및 휴식 아이콘, 대상 창의 연계 점수 링.", "单位框体：暴雪风格的名称与等级文字、战斗和休息图标，以及目标框体上的连击点环。", "單位框架：暴雪風格的名稱與等級文字、戰鬥和休息圖示，以及目標框架上的連擊點環。" },
    ["Forever nameplates redesigned: taller bars with the Retail texture, the name above the bar, a bronze border with softly rounded corners, and the level in a yellow box beside the bar."] = { "Placas de nombre Forever rediseñadas: barras más altas con la textura de Retail, el nombre sobre la barra, borde de bronce con esquinas suavemente redondeadas y el nivel en una caja amarilla junto a la barra.", "Forever-Namensplaketten überarbeitet: höhere Leisten mit der Retail-Textur, der Name über der Leiste, ein Bronzerahmen mit sanft abgerundeten Ecken und die Stufe in einem gelben Kasten neben der Leiste.", "Plaques de nom Forever remaniées : barres plus hautes avec la texture Retail, nom au-dessus de la barre, bordure bronze aux coins légèrement arrondis et niveau dans un encadré jaune à côté de la barre.", "Targhette Forever ridisegnate: barre più alte con la texture Retail, il nome sopra la barra, bordo bronzo con angoli leggermente arrotondati e il livello in un riquadro giallo accanto alla barra.", "Placas de nome Forever redesenhadas: barras mais altas com a textura do Retail, o nome acima da barra, borda de bronze com cantos levemente arredondados e o nível em uma caixa amarela ao lado da barra.", "Индикаторы здоровья Forever переработаны: более высокие полосы с текстурой Retail, имя над полосой, бронзовая рамка с мягко скруглёнными углами и уровень в жёлтом блоке рядом с полосой.", "Forever 이름표를 새로 디자인했습니다: Retail 텍스처의 더 높은 바, 바 위의 이름, 모서리가 살짝 둥근 청동 테두리, 바 옆의 노란 레벨 상자.", "重新设计 Forever 姓名板：血条更高并使用 Retail 材质，名称位于血条上方，青铜边框带有柔和圆角，等级显示在血条旁的黄色方框中。", "重新設計 Forever 名條：血條更高並使用 Retail 材質，名稱位於血條上方，青銅邊框帶有柔和圓角，等級顯示在血條旁的黃色方框中。" },
    ["Classic nameplates show the level as a gold number on a gold pill at the end of the bar and are larger by default."] = { "Las placas de nombre Classic muestran el nivel como un número dorado sobre una pastilla dorada al final de la barra y son más grandes por defecto.", "Classic-Namensplaketten zeigen die Stufe als goldene Zahl auf einer goldenen Kapsel am Ende der Leiste und sind standardmäßig größer.", "Les plaques de nom Classic affichent le niveau sous forme de chiffre doré sur une pastille dorée au bout de la barre et sont plus grandes par défaut.", "Le targhette Classic mostrano il livello come numero dorato su una pillola dorata a fine barra e sono più grandi per impostazione predefinita.", "As placas de nome Classic mostram o nível como um número dourado sobre uma pílula dourada no fim da barra e são maiores por padrão.", "Индикаторы здоровья Classic показывают уровень золотой цифрой на золотой плашке в конце полосы и по умолчанию стали крупнее.", "Classic 이름표는 바 끝의 금색 알약 위에 금색 숫자로 레벨을 표시하며 기본 크기가 더 커졌습니다.", "Classic 姓名板在血条末端的金色胶囊上以金色数字显示等级，并且默认尺寸更大。", "Classic 名條在血條末端的金色膠囊上以金色數字顯示等級，並且預設尺寸更大。" },
    ["Better 3D party portraits, and 3D portraits in circular Unit Frame portraits."] = { "Mejores retratos 3D en los marcos de grupo, y retratos 3D en los retratos circulares de los marcos de unidad.", "Bessere 3D-Porträts in den Gruppenfenstern sowie 3D-Porträts in runden Einheitenfenster-Porträts.", "Meilleurs portraits 3D dans les cadres de groupe, et portraits 3D dans les portraits circulaires des cadres d'unité.", "Ritratti 3D migliorati nei riquadri gruppo e ritratti 3D nei ritratti circolari dei riquadri unità.", "Retratos 3D melhores nos quadros de grupo e retratos 3D nos retratos circulares dos quadros de unidade.", "Улучшены 3D-портреты в рамках группы, а также добавлены 3D-портреты в круглых портретах рамок бойцов.", "파티 창의 3D 초상화가 개선되었고 원형 개체창 초상화에서도 3D 초상화를 지원합니다.", "改进了小队框体的 3D 头像，并且单位框体的圆形头像现在支持 3D 头像。", "改進了隊伍框架的 3D 頭像，並且單位框架的圓形頭像現在支援 3D 頭像。" },
    ["The Classic style shows the original Blizzard text on health and power bars, and its Rare/Elite ring hugs the portrait."] = { "El estilo Classic muestra el texto original de Blizzard en las barras de salud y poder, y su anillo de Raro/Élite se ajusta al retrato.", "Der Classic-Stil zeigt den originalen Blizzard-Text auf Leben- und Ressourcenleisten, und sein Selten-/Elite-Ring umschließt das Porträt eng.", "Le style Classic affiche le texte Blizzard d'origine sur les barres de vie et de ressource, et son anneau Rare/Élite épouse le portrait.", "Lo stile Classic mostra il testo originale di Blizzard sulle barre di salute e risorsa, e il suo anello Raro/Élite aderisce al ritratto.", "O estilo Classic mostra o texto original da Blizzard nas barras de vida e recurso, e seu anel de Raro/Elite se ajusta ao retrato.", "Стиль Classic показывает оригинальный текст Blizzard на полосах здоровья и ресурса, а его кольцо редких/элитных плотно облегает портрет.", "Classic 스타일은 생명력/자원 바에 블리자드 원래의 텍스트를 표시하며, 희귀/엘리트 링이 초상화에 딱 맞게 붙습니다.", "Classic 样式在生命值和能量条上显示暴雪原版文字，其稀有/精英环紧贴头像。", "Classic 樣式在生命值和能量條上顯示暴雪原版文字，其稀有/精英環緊貼頭像。" },
    ["Combo points use a look that matches each visual style by default."] = { "Los puntos de combo usan por defecto un aspecto acorde con cada estilo visual.", "Combopunkte verwenden standardmäßig ein zum jeweiligen visuellen Stil passendes Aussehen.", "Les points de combo adoptent par défaut un aspect adapté à chaque style visuel.", "I punti combo usano di default un aspetto coerente con ogni stile visivo.", "Os pontos de combo usam por padrão um visual que combina com cada estilo visual.", "По умолчанию приёмы в серии выглядят в соответствии с каждым визуальным стилем.", "연계 점수는 기본적으로 각 시각 스타일에 어울리는 모양을 사용합니다.", "连击点默认使用与每种视觉样式相匹配的外观。", "連擊點預設使用與每種視覺樣式相符的外觀。" },
    ["The Installer returns to the Visual Style page after a style change reloads the interface, and no longer reopens by itself if you closed it."] = { "El instalador vuelve a la página de estilo visual tras recargar la interfaz por un cambio de estilo, y ya no se reabre solo si lo cerraste.", "Der Installer kehrt nach einem Stilwechsel mit Neuladen zur Seite „Visueller Stil“ zurück und öffnet sich nicht mehr von selbst, wenn du ihn geschlossen hast.", "L'installateur revient à la page Style visuel après le rechargement dû à un changement de style, et ne se rouvre plus tout seul si vous l'avez fermé.", "L'installer torna alla pagina Stile visivo dopo il ricaricamento causato da un cambio di stile e non si riapre più da solo se lo hai chiuso.", "O instalador volta à página Estilo visual após a recarga causada por uma troca de estilo e não reabre mais sozinho se você o fechou.", "Установщик возвращается на страницу «Визуальный стиль» после перезагрузки из-за смены стиля и больше не открывается сам, если вы его закрыли.", "스타일 변경으로 UI를 다시 불러온 뒤 설치 도우미가 시각 스타일 페이지로 돌아오며, 직접 닫았다면 더 이상 저절로 다시 열리지 않습니다.", "因更换样式而重新加载界面后，安装向导会返回“视觉风格”页面；如果你已关闭它，不会再自动重新打开。", "因更換樣式而重新載入介面後，安裝精靈會返回「視覺風格」頁面；如果你已關閉它，不會再自動重新開啟。" },
    ["KUI no longer changes your UI scale or moves Edit Mode frames unless you choose to, and module on/off toggles apply correctly."] = { "KUI ya no cambia la escala de tu interfaz ni mueve los marcos del Modo de edición salvo que lo elijas, y los interruptores de activar/desactivar módulos se aplican correctamente.", "KUI ändert deine UI-Skalierung nicht mehr und verschiebt keine Bearbeitungsmodus-Fenster, außer du entscheidest dich dafür, und die Modulschalter greifen korrekt.", "KUI ne modifie plus l'échelle de l'interface ni ne déplace les cadres du mode Édition sauf si vous le choisissez, et les interrupteurs d'activation des modules s'appliquent correctement.", "KUI non modifica più la scala dell'interfaccia né sposta i riquadri della modalità Modifica a meno che tu non lo scelga, e gli interruttori di attivazione dei moduli vengono applicati correttamente.", "O KUI não altera mais a escala da interface nem move os quadros do Modo de Edição, a menos que você escolha, e os botões de ativar/desativar módulos são aplicados corretamente.", "KUI больше не меняет масштаб интерфейса и не двигает рамки режима правки, пока вы сами этого не выберете, а переключатели модулей применяются корректно.", "KUI는 직접 선택하지 않는 한 UI 크기를 바꾸거나 편집 모드 창을 옮기지 않으며, 모듈 켜기/끄기가 올바르게 적용됩니다.", "除非你主动选择，否则 KUI 不再更改界面缩放或移动编辑模式中的框体；模块开关也能正确生效。", "除非你主動選擇，否則 KUI 不再變更介面縮放或移動編輯模式中的框架；模組開關也能正確生效。" },
}

for key, values in pairs(translations) do
    for index, localeName in ipairs(localeOrder) do
        local locale = locales[localeName]
        local value = values[index]
        if locale and value then
            local current = rawget(locale, key)
            local englishValue = locales.enUS and rawget(locales.enUS, key)
            if current == nil or current == key or current == englishValue then locale[key] = value end
        end
    end
end
